"""Pydantic models and JSON Schema generation for inter-agent artifacts."""

from typing import Dict, List, Literal, Optional, Union
from pydantic import BaseModel, Field, field_validator


class TaskPlan(BaseModel):
    """Normalized plan generated by Manager."""
    id: str = Field(description="Unique task plan identifier")
    task_id: str = Field(description="Associated task id")
    name: str = Field(description="Descriptive task name")
    description: str = Field(description="Normalized requirement text")
    complexity: Literal["SIMPLE", "STRUCTURED"] = Field(
        default="SIMPLE", description="Determined complexity path"
    )
    files: List[str] = Field(
        default_factory=list, description="Target source files to be produced"
    )
    sprint_goals: List[str] = Field(
        default_factory=list, description="High-level goals for iteration"
    )
    acceptance_criteria: List[str] = Field(
        default_factory=list, description="Explicit, objectively testable acceptance criteria"
    )
    ambiguities: List[str] = Field(
        default_factory=list, description="Identified requirement ambiguities or missing constraints"
    )

    @field_validator("files", "sprint_goals", "acceptance_criteria", "ambiguities", mode="before")
    @classmethod
    def normalize_string_lists(cls, v):
        if isinstance(v, str):
            return [v.strip()]
        return v




class UserStory(BaseModel):
    """User story produced by RABot/Architect for structured tasks."""
    id: str = Field(description="User story identifier e.g. US-1")
    role: str = Field(description="User persona e.g. admin, user")
    action: str = Field(description="Intended action")
    goal: str = Field(description="Expected value or outcome")
    acceptance_criteria: List[str] = Field(
        default_factory=list, description="List of verifiable criteria"
    )
    priority: Literal["low", "medium", "high"] = Field(
        default="medium", description="Story priority"
    )
    estimate: int = Field(default=1, ge=1, description="Story point estimate")

    @field_validator("acceptance_criteria", mode="before")
    @classmethod
    def normalize_acceptance_criteria(cls, v):
        if isinstance(v, str):
            return [v.strip()]
        return v


class Architecture(BaseModel):
    """Architectural artifact produced by Architect for structured tasks."""
    components: List[Dict[str, str]] = Field(
        default_factory=list, description="List of components with name and responsibility"
    )
    uml_class_diagram: str = Field(
        default="", description="Mermaid or text class diagram representation"
    )
    file_structure: List[str] = Field(
        default_factory=list, description="Planned project file paths"
    )
    module_dependencies: Dict[str, List[str]] = Field(
        default_factory=dict, description="Module to imported local modules mapping"
    )

    @field_validator("file_structure", mode="before")
    @classmethod
    def normalize_file_structure(cls, v):
        if isinstance(v, str):
            return [v.strip()]
        return v


class CodePatch(BaseModel):
    """Code patch produced by Developer."""
    files: List[str] = Field(description="List of files touched in this patch")
    file_contents: Dict[str, str] = Field(
        default_factory=dict, description="Mapping of relative filepath to full file code"
    )
    summary: str = Field(description="Concise description of changes made")
    tests_expected: List[str] = Field(
        default_factory=list, description="Key behaviors expected to pass in testing"
    )

    @field_validator("files", mode="before")
    @classmethod
    def normalize_files(cls, v):
        if isinstance(v, str):
            return [v.strip()]
        return v

    @field_validator("tests_expected", mode="before")
    @classmethod
    def normalize_tests_expected(cls, v):
        if isinstance(v, str):
            return [v.strip()]
        return v


class ReviewReport(BaseModel):
    """Semantic and requirement review produced by Reviewer."""
    status: Literal["PASSED", "FAILED", "NEEDS_REVISION"] = Field(
        description="Overall review outcome"
    )
    critical_issues: int = Field(default=0, ge=0, description="Count of critical defects")
    major_issues: int = Field(default=0, ge=0, description="Count of major defects")
    minor_issues: int = Field(default=0, ge=0, description="Count of minor improvements")
    findings: List[str] = Field(
        default_factory=list, description="Actionable findings or bugs detected"
    )
    summary: str = Field(default="", description="Summary of review observations")

    @field_validator("status", mode="before")
    @classmethod
    def normalize_status(cls, v):
        if isinstance(v, str):
            clean = v.strip().upper()
            if "PASS" in clean:
                return "PASSED"
            if "FAIL" in clean:
                return "FAILED"
            if "REVIS" in clean or "NEED" in clean:
                return "NEEDS_REVISION"
        return v

    @field_validator("findings", mode="before")
    @classmethod
    def normalize_findings(cls, v):
        if isinstance(v, str):
            return [v.strip()]
        return v


class TestReport(BaseModel):
    """Diagnostic pytest test report produced by internal Tester."""
    __test__ = False
    total_tests: int = Field(default=0, ge=0, description="Total executed tests")
    passed_tests: int = Field(default=0, ge=0, description="Count of passing tests")
    failed_tests: int = Field(default=0, ge=0, description="Count of failing tests")
    pass_rate: float = Field(
        default=0.0, ge=0.0, le=1.0, description="Passed tests / total tests"
    )
    coverage: float = Field(
        default=0.0, ge=0.0, le=100.0, description="Line coverage percentage"
    )
    details: List[str] = Field(
        default_factory=list, description="Individual test execution output"
    )


class ReflectionDecision(BaseModel):
    """Adaptive stopping decision produced by Reflection/Stopper."""
    decision: Literal["CONTINUE", "STOP"] = Field(
        description="Whether to iterate or stop"
    )
    reason: str = Field(description="Stopping or continuation rationale")
    adaptive_score: float = Field(
        default=0.0, ge=0.0, le=1.0, description="Current iteration adaptive score S_t"
    )
    marginal_gain: float = Field(
        default=0.0, description="Delta from previous score S_t - S_{t-1}"
    )
    iteration: int = Field(default=1, ge=1, description="Current iteration index")


ARTIFACT_CLASSES = {
    "TaskPlan": TaskPlan,
    "UserStory": UserStory,
    "Architecture": Architecture,
    "CodePatch": CodePatch,
    "ReviewReport": ReviewReport,
    "TestReport": TestReport,
    "ReflectionDecision": ReflectionDecision,
}


def get_json_schema(artifact_type: str) -> dict:
    """Export standard JSON Schema from canonical Pydantic models."""
    if artifact_type not in ARTIFACT_CLASSES:
        raise ValueError(f"Unknown artifact type: {artifact_type}")
    return ARTIFACT_CLASSES[artifact_type].model_json_schema()
